  static MdiMetadata? maybeMetadataOf(IconData icon) {
    if (icon.fontFamily != 'Material Design Icons' ||
        icon.fontPackage != 'flutter_material_design_icons') {
      return null;
    }

    return _metadataByCodePoint[icon.codePoint];
  }
}

extension MdiIconsExtension on IconData {
  MdiMetadata? get mdiMetadata => MdiIcons.maybeMetadataOf(this);

  MdiMetadata get metadata {
    final metadata = mdiMetadata;
    if (metadata != null) {
      return metadata;
    }

    throw StateError('IconData is not part of MdiIcons');
  }
}
